"""report_assets/report_notes.md: the results mapped onto the seven report sections. Every number is read from results.json."""
from __future__ import annotations

from typing import Any, Mapping

from .report import SNR_CAVEAT, num

REFERENCES_VERIFIED = [
    "S. Al-Emadi, A. Al-Ali, A. Mohammad, A. Al-Ali, \"Audio based drone detection and identification using deep learning\", 2019 15th International Wireless Communications and Mobile Computing Conference (IWCMC), IEEE, 2019. DOI 10.1109/IWCMC.2019.8766732. (Checked on the Qatar University repository record.) The dataset licence forbids defence use, so it is cited but not used.",
    "S. Al-Emadi, A. Al-Ali, A. Al-Ali, \"Audio-Based Drone Detection and Identification Using Deep Learning Techniques\" (the MDPI page also shows the phrase \"Dataset Enhancement through Generative Adversarial Networks\"; copy the exact title from the page), Sensors 21(15), 4953, 2021. DOI 10.3390/s21154953. (Checked on the MDPI page. The PMC id PMC8348319 in the brief could not be opened here, so cite the MDPI record.)",
    "M. Y. Wang, M. Linn, A. P. Berg, Q. Zhang, \"A Multiclass Acoustic Dataset and Interactive Tool for Analyzing Drone Signatures in Real-World Environments\", arXiv:2509.04715, 2025. (Checked on arXiv.)",
    "M. Ohlenbusch, A. Ahrens, C. Rollwage, J. Bitzer, \"Robust Drone Detection for Acoustic Monitoring Applications\", EUSIPCO 2020. (Checked on the EURASIP proceedings PDF. The title ends in \"Applications\", which the brief omitted. Check the umlaut in the last author's name and the page numbers before submitting.)",
    "S. Kümmritz, L. Paul, \"Comprehensive Database of UAV Sounds for Machine Learning\", 10th Convention of the European Acoustics Association (Forum Acusticum 2023), Turin, 11 to 15 September 2023. (Checked on the proceedings PDF.)",
]
REFERENCES_NOT_CHECKED = [
    "K. J. Piczak, \"ESC: Dataset for Environmental Sound Classification\", ACM Multimedia 2015.",
    "J. Salamon, C. Jacoby, J. P. Bello, \"A Dataset and Taxonomy for Urban Sound Research\", ACM Multimedia 2014.",
    "S. Davis, P. Mermelstein, \"Comparison of Parametric Representations for Monosyllabic Word Recognition in Continuously Spoken Sentences\", IEEE Transactions on Acoustics, Speech, and Signal Processing, 1980.",
    "S. F. Boll, \"Suppression of Acoustic Noise in Speech Using Spectral Subtraction\", IEEE Transactions on Acoustics, Speech, and Signal Processing, 1979.",
    "C. Cortes, V. Vapnik, \"Support-Vector Networks\", Machine Learning, 1995.",
    "J. C. Platt, \"Probabilistic Outputs for Support Vector Machines and Comparisons to Regularized Likelihood Methods\", 1999.",
    "I. T. Jolliffe, \"Principal Component Analysis\", Springer.",
    "G. H. Golub, C. F. Van Loan, \"Matrix Computations\" (SVD, Eckart-Young low-rank approximation).",
    "ISO 9613-1, Acoustics: attenuation of sound during propagation outdoors, Part 1: calculation of the absorption of sound by the atmosphere. (Only needed if alpha is used; the default config sets alpha to 0.)",
    "DADS dataset card, huggingface.co/datasets/gr1047/drone-audio-detection-samples (download failed on the author's network, so it was not used).",
]


def build_notes(res: Mapping[str, Any], cfg: Mapping[str, Any]) -> str:
    cv = res["cv_default"]
    fm = cv["fold_mean_std"]
    ds = cv["dataset"]
    ab = res["ablation"]
    pv = next(v for v in res["pca_variance"]["per_variant"] if v["variant"] == "none")
    pc1 = next(t for t in res["pca_variance"]["top_loadings"] if t["component"] == "PC1")
    sp = lambda c: next(x["spearman"] for x in res["pca_variance"]["level_feature_spearman"] if x["variant"] == "none" and x["component"] == c and x["feature"] == "rms_mean")  # noqa: E731
    fa = res["false_alarms"]
    op, mt = fa["at_operating_point"], fa["at_model_threshold"]
    sel = fa.get("selection_source", "esc50_crossfit")
    sc = res["stream_check"]
    final = res["final_model"]
    lat = final["latency"]["stages"]["total"]
    rg = res.get("range", {})
    bench = res.get("bench", {})
    budgets = "; ".join(f"{b}/h: t_on {num(v['t_on'], 2)}, recall {num(v['event_recall_mean'], 3)}" for b, v in sorted(fa["recall_by_false_alarm_budget"].items(), key=lambda kv: float(kv[0])))
    cd = res["data"]
    L = []
    a = L.append
    a("# Report notes: SENTINEL-A (Project 01)\n")
    a("Generated by `scripts/make_report_notes.py` from `results/results.json`. Every number below was read from that file. "
      "Edit the wording in your own report, not the numbers.\n")
    a("**Scope you must state in the report:** the data are ESC-50 only (aircraft versus ambient). There is no drone class: the DADS download failed on this network and its licence question is open, and the Al-Emadi set forbids defence use. "
      "No number below is a drone result.\n")
    a("## 1. Introduction to PCA, SVD and SVM\n")
    a("- PCA via SVD: centre the feature matrix X (n x p), X = U S V^T, the principal axes are the rows of V^T, the variance along axis k is s_k^2 / (n - 1). `SVDPCA` in `src/sentinel/svdpca.py` does exactly this with `numpy.linalg.svd`; `tests/test_svdpca.py` checks it against `sklearn.decomposition.PCA` (components equal up to sign).")
    a("- Truncated SVD works on the uncentred matrix; the first component then mostly carries the mean (level) rather than the variance. This project compares both (M2).")
    a("- Eckart-Young: keeping the k largest singular values gives the best rank-k approximation in the Frobenius norm. Used here for denoising a magnitude spectrogram (keep k singular values by cumulative energy or by the elbow).")
    a("- SVM: maximum-margin classifier; the RBF kernel K(x, y) = exp(-gamma ||x - y||^2) handles non-linear boundaries; C trades margin against training errors; `class_weight=balanced` offsets the class imbalance. Platt scaling maps the SVM score to a probability.")
    a(f"- On this data, {pv['n_features']} z-scored features need {pv['k90']} components for 90% of the variance, {pv['k95']} for 95%, {pv['k99']} for 99% (denoising variant none). The first component carries {num(100 * pv['pc1_ratio'], 1)}% of the variance; its largest loadings are {', '.join(f for f, _ in pc1['top_features'][:3])} (frame-to-frame spectral change, not loudness: Spearman with window rms {num(sp('PC1'), 2, True)}). PC2 is partly a loudness axis (Spearman with window rms {num(sp('PC2'), 2, True)}).\n")
    a("## 2. Problem statement\n")
    a("- Task: classify 1 s windows (0.5 s hop, 16 kHz mono) and turn window probabilities into alerts and events a person on watch can use (perimeter surveillance framing).")
    a(f"- Classes: {', '.join(final['model']['classes'])}; alert target class: {', '.join(final['model']['targets'])}. A drone class is the intended third class but no drone data was available.")
    a(f"- Data: {cd['n_files']} ESC-50 clips from {cd['n_groups']} source recordings. Aircraft {cd['by_class']['aircraft']['files']} files ({cd['by_class']['aircraft']['windows']} windows), ambient {cd['by_class']['ambient']['files']} files ({cd['by_class']['ambient']['windows']} windows); "
      f"{cd['by_dataset_bucket']['esc50/ambient_hard_negative']['files']} of the ambient files are hard negatives (engine, train, vacuum cleaner, washing machine, chainsaw, hand saw).")
    a(f"- Used for training and CV after the silence gate: {ds['n_used']} windows ({ds['windows']['aircraft']} aircraft, {ds['windows']['ambient']} ambient). The aircraft class is {num(100 * ds['windows']['aircraft'] / ds['n_used'], 1)}% of windows.")
    a("- No leakage: grouped splits on the Freesound source recording id (StratifiedGroupKFold, 5 folds, seed 1337).\n")
    a("## 3. Implementation details\n")
    a("- Preprocessing: resample to 16 kHz, DC removal, Butterworth band-pass 100 to 7000 Hz (order 4, second-order sections); zero-phase `sosfiltfilt` offline, causal `sosfilt` with carried state live.")
    a(f"- Causal versus zero-phase filter: grouped-CV balanced accuracy {num(sc['causal_vs_zero_phase']['oof']['zero_phase_trained_tested_zero_phase']['ba_fold_mean'], 3)} (zero-phase), {num(sc['causal_vs_zero_phase']['oof']['zero_phase_trained_tested_causal']['ba_fold_mean'], 3)} (trained zero-phase, tested causal); fold-paired change {num(sc['causal_vs_zero_phase']['ba_drop_causal_vs_zero_phase_fold_mean'], 4, True)}.")
    a("- Noise reduction, all from scratch: spectral subtraction, Wiener gain, truncated-SVD denoising of the magnitude spectrogram (energy target and elbow).")
    a(f"- Features: {pv['n_features']} per window (20 MFCC with delta and delta-delta as mean and std, spectral centroid, bandwidth, rolloff, flatness, contrast, zero-crossing rate, RMS). Standardised on the training folds only.")
    fc = final["final_config"]
    a(f"- Saved model: denoising {fc['variant']}, PCA {fc['pca']} components, RBF SVM C={fc['svm']['C']}, class weight balanced, Platt calibration fitted on out-of-fold scores. It is the untuned default fixed before the ablation ran.")
    a(f"- Ablation: {ab['n_configs']} configurations (denoising x level features x PCA size x kernel/C), same grouped folds for all. Best cell {ab['grid_best']['variant']}, PCA {ab['grid_best']['pca']}, {ab['grid_best']['kernel']}: balanced accuracy {num(ab['grid_best']['balanced_accuracy_mean'], 3)}, optimistic because it was chosen on the data it is scored on; nested CV gives {num(ab['nested']['pooled_balanced_accuracy'], 3)} pooled.")
    a(f"- Alert logic (`src/sentinel/alerting.py`, pure functions): EMA alpha {cfg['m5']['alert']['ema_alpha']}, ON when {cfg['m5']['alert']['n_on']} of the last {cfg['m5']['alert']['m_window']} smoothed windows are at or above t_on, OFF after {cfg['m5']['alert']['k_off']} windows below t_off = {cfg['m5']['alert']['t_off_ratio']} t_on, minimum event {cfg['m5']['alert']['min_event_s']} s, merge gap {cfg['m5']['alert']['merge_gap_s']} s. Engineering values, not tuned.")
    a("- Event feed: events.jsonl and events.csv per run, and an optional ZeroMQ PUB stream (`tcp://127.0.0.1:5556`, topic `acoustic`, two frames: topic and JSON).\n")
    a("## 4. Python programming\n")
    a("- Package `src/sentinel/` (config, preprocess, windowing, features, denoise, svdpca, cv, pipeline, m3, calibration, noise, robustness, bundle, alerting, engine, sources, runlog, monitor, zmqpub, scenarios, range_model, bench, report, notes), scripts in `scripts/`, tests in `tests/`, all tunables in `configs/default.yaml`, numbers in `results/results.json`.")
    a("- Design points worth a paragraph: pure-function alert state machine with immutable state; `AudioSource` abstraction (file, TCP from Windows, sounddevice); one engine used live and offline (chunk-size invariance is tested); a model bundle that refuses to load when the feature config differs.")
    a(f"- Speed: median {num(lat['median_ms'], 2)} ms per 0.5 s hop on the model alone ({num(100 * lat['share_of_hop_median'], 2)}% of the hop); whole engine real-time factor {num(sc['speed']['real_time_factor'], 4)} (target below 0.2).")
    a(f"- Model on disk: {num(final['footprint']['joblib_file_bytes'] / 1024, 0)} KiB.\n")
    a("## 5. Results and discussion\n")
    a(f"- Window classifier, grouped CV (default pipeline): balanced accuracy {num(fm['balanced_accuracy_mean'], 3)} ± {num(fm['balanced_accuracy_std'], 3)}; aircraft recall {num(fm['recall_aircraft_mean'], 3)}, aircraft precision {num(fm['precision_aircraft_mean'], 3)}, AUC {num(fm['auc_aircraft_mean'], 3)}; specificity on hard negatives {num(fm['specificity_hard_negative_mean'], 3)} (plain ambient {num(cv['pooled_oof']['specificity_plain'], 3)}). Label-permutation check: {', '.join(num(x, 3) for x in cv['label_permutation_balanced_accuracy'])} (chance level is 0.5).")
    a(f"- Alerts at the model threshold (t_on {num(mt['t_on'], 3)}): {num(mt['false_alarms'][sel]['per_hour'], 1)} false alarms per hour on {num(mt['false_alarms'][sel]['hours'], 2)} h of {sel} audio, mean event recall {num(mt['event_recall_mean'], 3)}.")
    a(f"- Operating point under the rule at most {num(fa['max_false_alarms_per_hour'], 0)} false alarm per hour with the best mean event recall: t_on {num(op['t_on'], 2)}, {op['false_alarms'][sel]['count']} false alarms in {num(op['false_alarms'][sel]['hours'], 2)} h (95% upper bound {num(op['false_alarms'][sel]['per_hour_ci95'][1], 1)} per hour), mean event recall {num(op['event_recall_mean'], 3)}.")
    a(f"- Recall for other false-alarm budgets: {budgets}.")
    a("- Event recall by scenario SNR at the operating point: " + ", ".join(f"{k} dB {num(v['event_recall'], 3)} ({v['detected']}/{v['clips']})" for k, v in sorted(op["by_snr"].items(), key=lambda kv: -float(kv[0]))) + ".")
    a("- Discussion points: the window classifier is weak at event level (a property of the model and data, not of the unit-tested alert logic); the alert parameters were not tuned and could move the trade-off; part of the low-SNR recall at low thresholds is chance, because the background itself raises false alarms.")
    own = fa["hours"].get("own", 0) > 0
    a("- Event SNR estimate: validated against pink noise in M5 (bias about " + num(sc["snr_estimate"]["by_nominal_snr_db"]["+10"]["bias_db"], 1, True) + " dB at +10 dB nominal), but not meaningful on the ESC-50 scenario streams. " + SNR_CAVEAT)
    a("- Honest limits: " + ("false-alarm rate includes real long recordings." if own else "no real long recordings, so the false-alarm rate comes from ESC-50 clips only (abruptly joined clips, a stress test) and the 1 per hour target is not validated on continuous audio."))
    if rg:
        if rg["snr_min_reached"]:
            a(f"- Range model: snr_min {num(rg['snr_min_db'], 1, True)} dB on `{rg['primary_curve']}`. " + (f"Estimate {num(rg['range_estimate_m'], 1)} m (model estimate, not a measurement)." if rg["range_estimate_m"] is not None else "No range estimate: " + "; ".join(rg["range_estimate_missing_inputs"]) + "."))
        else:
            a(f"- Range model: the condition `recall >= {num(rg['recall_target'], 2)}` is never met (best recall {num(rg['curve_summary'][rg['primary_curve']]['max_recall'], 3)} on `{rg['primary_curve']}`), so snr_min is reported as not reached and the range is shown only as a sensitivity table for hypothetical required SNRs. The drone source level is not assumed (TODO_CITE).")
    a("- Bench distance test: " + ("measured, see results/tables/m7_bench.csv. Indoor reverberation breaks the free-field assumption." if bench.get("available") else "no bench recordings were made, so nothing is claimed about measured distances."))
    a("- Calibration caveat: probabilities are calibrated for clean ESC-50 audio at ESC-50 prevalence. The saved model is in-sample on ESC-50; all accuracy numbers come from grouped CV or cross-fitted models.\n")
    a("## 6. Conclusion\n")
    a(f"- What works: a complete, tested chain from audio to events (filtering, MFCC features, PCA via SVD, SVM, calibrated probabilities, alert logic, event feed) that runs {num(1 / max(sc['speed']['real_time_factor'], 1e-9), 0)} times faster than real time on a laptop CPU.")
    a(f"- What the numbers say: window-level balanced accuracy {num(fm['balanced_accuracy_mean'], 2)} on ESC-50 aircraft versus ambient; at one false alarm per hour the event recall is {num(op['event_recall_mean'], 3)}. The chain is sound, the classifier is the weak part.")
    a("- Next steps: add real drone recordings with a licence that allows this use, validate false alarms on at least one hour of continuous site audio, tune the alert parameters on that audio, and measure the source level and range.\n")
    a("## 7. References\n")
    a("Checked against the source page while preparing this file:\n")
    for r in REFERENCES_VERIFIED:
        a(f"- {r}")
    a("\nNot checked here (well-known references, so check volume, pages and DOI before you cite them):\n")
    for r in REFERENCES_NOT_CHECKED:
        a(f"- {r}")
    return "\n".join(L) + "\n"
